<script src="https://www.google.com/recaptcha/api.js" async defer></script>
<script>

    function recaptchaVerified() {
        document.getElementById('recaptcha-error').innerText = '';
    }
    const disposableDomains = [
            'mailinator.com', '10minutemail.com', 'guerrillamail.com', 'tempmail.com',
            'temp-mail.org', 'throwawaymail.com', 'maildrop.cc', 'dispostable.com',
            'getairmail.com', 'moakt.com', 'spamgourmet.com', 'yopmail.com',
            'sharklasers.com', 'mailnesia.com', 'fakemail.net', 'emailondeck.com',
            'trashmail.com', 'mintemail.com', 'mytemp.email'
        ];
        
        function isDisposableEmail(email) {
            const domain = email.split('@')[1]?.toLowerCase();
            return disposableDomains.includes(domain);
        }

    $(document).ready(function () {
        $('#brandForm input, #brandForm textarea, #brandForm select').on('input change', function () {
            let fieldId = $(this).attr('id');
            let value = $(this).val().trim();
            let errorId = '#error-' + fieldId;

            if (value === '') {
                switch (fieldId) {
                    case 'name':
                        $(errorId).text('Please enter your full name');
                        break;
                    case 'company_name':
                        $(errorId).text('Please enter your company name');
                        break;
                    case 'number':
                        $(errorId).text('Please enter your phone number');
                        break;
                    case 'email':
                        $(errorId).text('Please enter your email');
                        break;
                    case 'interested_in':
                        $(errorId).text('Please select a service');
                        break;
                    default:
                        $(errorId).text('');
                }
            } else {
                if (fieldId === 'number' && !/^\d{10,15}$/.test(value)) {
                    $('#error-number').text('Phone number must be between 10 to 15 digits');
                } else if (fieldId === 'email') {
                    if (!/^\S+@\S+\.\S+$/.test(value)) {
                        $('#error-email').text('Please enter a valid email');
                    } else if (isDisposableEmail(value)) {
                        $('#error-email').text('Invalid email addresses are not allowed');
                    } else {
                        $('#error-email').text('');
                    }
                } else {
                    $(errorId).text('');
                }
            }
        });

        $('#brandForm').on('submit', function (e) {
            e.preventDefault();
            let isValid = true;
            $('.error').text('');

            if ($('#name').val().trim() === '') {
                $('#error-name').text('Please enter your full name');
                isValid = false;
            }

            if ($('#company_name').val().trim() === '') {
                $('#error-company_name').text('Please enter your company name');
                isValid = false;
            }

            let number = $('#number').val().trim();
            if (number === '') {
                $('#error-number').text('Please enter your phone number');
                isValid = false;
            } else if (!/^\d{10,15}$/.test(number)) {
                $('#error-number').text('Phone number must be between 10 to 15 digits');
                isValid = false;
            }

            let email = $('#email').val().trim();
            if (email === '') {
                $('#error-email').text('Please enter your email');
                isValid = false;
            } else if (!/^\S+@\S+\.\S+$/.test(email)) {
                $('#error-email').text('Please enter a valid email');
                isValid = false;
            } else if (isDisposableEmail(email)) {
                    $('#error-email').text('Invalid email addresses are not allowed');
                    isValid = false;
            }

            if ($('#interested_in').val() === '') {
                $('#error-interested_in').text('Please select a service');
                isValid = false;
            }

            if (grecaptcha.getResponse() === '') {
                $('#recaptcha-error').text('Please verify that you are not a robot');
                isValid = false;
            }

            if (isValid) {
            const submitBtn = $(this).find('button[type="submit"]');
            submitBtn.prop('disabled', true).text('Submitting...');
            this.submit();
        }
            // if (isValid) {
            //     this.submit(); // only submit if valid
            // }
        });
    });
</script>



<style>
.error {
    color: red;
    font-size: 14px;
}
</style>